import glob, subprocess, sys
from pathlib import Path
SRC = '"""BGE-M3 dense + sparse (lexical weights) + multi-vector (ColBERT) scores of candidate pairs, every passage (MaxP).\n\n    python m3_multi.py --data DIR --cands cands.parquet --out DIR [--cut vi800,zh200,en200] [--part I/N]\n\nSame inputs as rerank.py (docstore parts + query.parquet under --data, cands.parquet of (qid, doc_id, set, rank)).\nPassages are those of rerank.split_passages (~1500 chars, title on each, whole document). Every passage of a doc\nis encoded once and scored against every query whose pool holds the doc; a pair keeps the max over its passages\nof each score and the passage that gave it. The heads follow the reference model (FlagEmbedding BGEM3FlagModel):\ndense = CLS, L2-normalised, dot product; sparse = relu(sparse_linear(h)) per token, max per token id, special\ntokens dropped, score = sum over shared ids of w_q * w_p; colbert = normalise(colbert_linear(h[1:])), score =\nmean over query tokens of the max similarity over passage tokens. --part I/N keeps docs with doc_id % N == I\n(each doc is encoded by one kernel only); one worker per GPU.\nOutput: m3multi.parquet (qid, doc_id, dense, sparse, colbert, p_dense, p_sparse, p_colbert, n_passages)\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport glob\nimport gzip\nimport json\nimport subprocess\nimport sys\nimport time\nfrom collections import defaultdict\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom rerank import find_input, split_passages\n\nT0 = time.time()\nSPECIAL = {0, 1, 2, 3}  # XLM-R <s> <pad> </s> <unk>\n\n\ndef log(msg: str) -> None:\n    print(f"[{time.time() - T0:7.0f}s] {msg}", flush=True)\n\n\ndef sparse_dict(ids: np.ndarray, w: np.ndarray) -> dict[int, float]:\n    out: dict[int, float] = {}\n    for t, x in zip(ids.tolist(), w.tolist()):\n        if t not in SPECIAL and x > out.get(t, 0.0):\n            out[t] = x\n    return out\n\n\ndef load(args, g: int, n: int):\n    """Cands of this kernel part and GPU worker, query texts, passages of the docs."""\n    cands = pd.read_parquet(args.cands if args.cands.exists() else find_input(args.cands.name))\n    if args.cut:\n        cut = {s[:2]: int(s[2:]) for s in args.cut.split(",")}\n        cands = cands[cands["rank"] < cands["set"].str[:2].map(cut)]\n    i, k = (int(x) for x in args.part.split("/"))\n    cands = cands[cands["doc_id"] % k == i]\n    docs_all = np.sort(cands["doc_id"].unique())\n    cands = cands[cands["doc_id"].isin(set(docs_all[g::n]))]\n    queries = pd.read_parquet(glob.glob(f"{args.data}/**/query.parquet", recursive=True)[0])\n    qtext = dict(zip(queries["id"].astype(int), queries["query"]))\n    need = set(cands["doc_id"].astype(int))\n    docs = {}\n    for part in sorted(glob.glob(f"{args.data}/**/part-*.jsonl*", recursive=True)):\n        opener = gzip.open if part.endswith(".gz") else open\n        with opener(part, "rt", encoding="utf-8") as f:\n            for line in f:\n                d = json.loads(line)\n                if d["id"] in need and d["id"] not in docs:\n                    docs[d["id"]] = split_passages(d["t"], d["x"])\n    by_doc = defaultdict(list)\n    for q, d in zip(cands["qid"].astype(int), cands["doc_id"].astype(int)):\n        by_doc[d].append(q)\n    return by_doc, qtext, docs\n\n\ndef worker(args) -> None:\n    import torch\n    from huggingface_hub import hf_hub_download\n    from transformers import AutoModel, AutoTokenizer\n    g, n = args.worker, args.ngpu\n    by_doc, qtext, docs = load(args, g, n)\n    qids = sorted({q for qs in by_doc.values() for q in qs})\n    flat = [(d, k, p) for d in by_doc if d in docs for k, p in enumerate(docs[d])]\n    log(f"worker {g}: {len(by_doc):,} docs, {len(flat):,} passages, {sum(map(len, by_doc.values())):,} pairs")\n    device = f"cuda:{g}" if torch.cuda.is_available() else "cpu"\n    dtype = torch.float16 if device != "cpu" else torch.float32\n    tok = AutoTokenizer.from_pretrained(args.model)\n    model = AutoModel.from_pretrained(args.model, torch_dtype=dtype).to(device).eval()\n    colbert = torch.nn.Linear(1024, 1024)\n    colbert.load_state_dict(torch.load(hf_hub_download(args.model, "colbert_linear.pt"), map_location="cpu"))\n    sparse = torch.nn.Linear(1024, 1)\n    sparse.load_state_dict(torch.load(hf_hub_download(args.model, "sparse_linear.pt"), map_location="cpu"))\n    colbert, sparse = colbert.to(device, dtype).eval(), sparse.to(device, dtype).eval()\n\n    def encode(texts: list[str], max_len: int):\n        enc = tok(texts, padding=True, truncation=True, max_length=max_len, return_tensors="pt").to(device)\n        with torch.inference_mode():\n            h = model(**enc).last_hidden_state\n            dense = torch.nn.functional.normalize(h[:, 0].float(), dim=-1)\n            sw = torch.relu(sparse(h)).squeeze(-1).float()\n            mask = enc["attention_mask"][:, 1:].float()\n            cv = torch.nn.functional.normalize(colbert(h[:, 1:]).float(), dim=-1) * mask[..., None]\n        return dense, sw.cpu().numpy(), cv, mask, enc["input_ids"].cpu().numpy()\n\n    qenc = {}\n    for lo in range(0, len(qids), 64):\n        batch = qids[lo:lo + 64]\n        dense, sw, cv, mask, ids = encode([qtext[q] for q in batch], 128)\n        for i, q in enumerate(batch):\n            qenc[q] = (dense[i], sparse_dict(ids[i], sw[i]), cv[i, :int(mask[i].sum())])\n    best: dict[tuple[int, int], list[float]] = {}  # (q, d) -> [dense, sparse, colbert, p_dense, p_sparse, p_colbert]\n    order = np.argsort([-len(p[2]) for p in flat], kind="stable")\n    for lo in range(0, len(order), args.batch):\n        idx = order[lo:lo + args.batch]\n        dense, sw, cv, mask, ids = encode([flat[i][2] for i in idx], args.max_len)\n        for j, i in enumerate(idx):\n            d, k, _ = flat[i]\n            ps = sparse_dict(ids[j], sw[j])\n            pc = cv[j, :int(mask[j].sum())]\n            for q in by_doc[d]:\n                qd, qs, qc = qenc[q]\n                s = (float(qd @ dense[j]), sum(w * ps[t] for t, w in qs.items() if t in ps),\n                     float((qc @ pc.T).max(dim=-1).values.mean()))\n                cur = best.setdefault((q, d), [-1e9, -1e9, -1e9, -1, -1, -1])\n                for m in range(3):\n                    if s[m] > cur[m]:\n                        cur[m], cur[3 + m] = s[m], k\n        if (lo // args.batch) % 200 == 0:\n            log(f"worker {g}: {lo + len(idx):,}/{len(flat):,} passages")\n    rows = [(q, d, *v, len(docs[d])) for (q, d), v in best.items()]\n    df = pd.DataFrame(rows, columns=["qid", "doc_id", "dense", "sparse", "colbert", "p_dense", "p_sparse",\n                                     "p_colbert", "n_passages"])\n    df.to_parquet(args.out / f"m3multi_w{g}.parquet", index=False)\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    ap.add_argument("--data", type=Path, required=True)\n    ap.add_argument("--cands", type=Path, required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--model", default="BAAI/bge-m3")\n    ap.add_argument("--cut", default="", help="e.g. vi800,zh200,en200: keep cands with rank < N in their set")\n    ap.add_argument("--part", default="0/1", help="I/N: docs with doc_id %% N == I")\n    ap.add_argument("--batch", type=int, default=32)\n    ap.add_argument("--max-len", type=int, default=512)\n    ap.add_argument("--worker", type=int, default=-1)\n    ap.add_argument("--ngpu", type=int, default=1)\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n    if args.worker >= 0:\n        worker(args)\n        return\n    import torch\n    n = max(1, torch.cuda.device_count())\n    procs = [subprocess.Popen([sys.executable, __file__, *sys.argv[1:], "--worker", str(g), "--ngpu", str(n)])\n             for g in range(n)]\n    if any(p.wait() != 0 for p in procs):\n        raise SystemExit("a worker failed")\n    parts = [args.out / f"m3multi_w{g}.parquet" for g in range(n)]\n    pd.concat([pd.read_parquet(p) for p in parts]).to_parquet(args.out / "m3multi.parquet", index=False)\n    for p in parts:\n        p.unlink()\n    log("done")\n\n\nif __name__ == "__main__":\n    main()\n'
MODULES = {'rerank.py': '"""Cross-encoder reranking of candidate documents on Kaggle GPU(s), full text.\n\n    python rerank.py --data DIR --cands candidates.parquet --out DIR [--model BAAI/bge-reranker-v2-m3]\n                     [--part I/N] [--max-queries N]\n\ncandidates.parquet: (qid, doc_id) pairs, e.g. the union of BM25 and dense top-K. Every document is\nsplit into ~1500-char passages (title on each); doc score = max passage logit. --part I/N keeps\nqueries with index % N == I so several accounts can share the work. One worker per GPU.\n--best-passages K scores only the K passages per pair sharing the most query words (diacritic-free).\n--cut vi800,zh200,en200 keeps cands with rank < N in their language set (cands.parquet column set, rank).\nOutput: rerank.parquet (qid, doc_id, score, best_passage); --keep-all adds passages.parquet\n(qid, doc_id, passage, score) with the score of every passage.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport glob\nimport gzip\nimport json\nimport re\nimport subprocess\nimport sys\nimport time\nimport unicodedata\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nT0 = time.time()\nPASSAGE_CHARS = 1500\n\n\ndef log(msg: str) -> None:\n    print(f"[{time.time() - T0:7.0f}s] {msg}", flush=True)\n\n\ndef split_passages(title: str, text: str) -> list[str]:\n    pieces = []\n    for para in text.split("\\n"):\n        while len(para) > PASSAGE_CHARS:\n            pieces.append(para[:PASSAGE_CHARS])\n            para = para[PASSAGE_CHARS:]\n        if para.strip():\n            pieces.append(para)\n    out, buf = [], ""\n    for p in pieces:\n        if buf and len(buf) + len(p) > PASSAGE_CHARS:\n            out.append(buf)\n            buf = ""\n        buf = f"{buf}\\n{p}" if buf else p\n    if buf or not out:\n        out.append(buf)\n    return [f"{title}\\n{p}".strip() for p in out]\n\n\nD_FOLD = str.maketrans({chr(0x111): "d", chr(0x110): "d"})\nWORD = re.compile(r"\\w+")\n\n\ndef words(text: str) -> set[str]:\n    """Lower-case, diacritic-free words longer than one character."""\n    t = unicodedata.normalize("NFD", text.lower())\n    t = "".join(c for c in t if not unicodedata.combining(c)).translate(D_FOLD)\n    return {w for w in WORD.findall(t) if len(w) > 1}\n\n\ndef best_passages(passages: list[str], qwords: set[str], k: int) -> list[str]:\n    """The k passages sharing the most query words (ties: earliest), kept in document order."""\n    order = sorted(range(len(passages)), key=lambda i: (-len(words(passages[i]) & qwords), i))[:k]\n    return [passages[i] for i in sorted(order)]\n\n\ndef find_input(name: str) -> Path:\n    """Resolve a file relative to the working tree or a sibling ``input`` mount."""\n    if Path(name).exists():\n        return Path(name)\n    roots = [Path.cwd()]\n    for parent in (Path.cwd(), *Path.cwd().parents):\n        mount = parent / "input"\n        if mount.is_dir():\n            roots.append(mount)\n    for root in roots:\n        hits = sorted(root.glob(f"**/{name}"))\n        if hits:\n            return Path(hits[0])\n    raise FileNotFoundError(name)\n\n\ndef load_inputs(args):\n    if not args.cands.exists():  # bare file name: look under the input mounts\n        args.cands = find_input(args.cands.name)\n    cands = pd.read_parquet(args.cands)\n    if getattr(args, "cut", ""):  # e.g. vi800,zh200,en200: rank < N within the language set of cands.parquet\n        cut = {s[:2]: int(s[2:]) for s in args.cut.split(",")}\n        cands = cands[cands["rank"] < cands["set"].str[:2].map(cut)]\n    qids = sorted(cands["qid"].unique())\n    i, n = (int(x) for x in args.part.split("/"))\n    keep = set(qids[i::n][: args.max_queries] if args.max_queries else qids[i::n])\n    cands = cands[cands["qid"].isin(keep)]\n    queries = pd.read_parquet(glob.glob(f"{args.data}/**/query.parquet", recursive=True)[0])\n    qtext = dict(zip(queries["id"].astype(int), queries["query"]))\n    need = set(cands["doc_id"].astype(int))\n    docs = {}\n    for part in sorted(glob.glob(f"{args.data}/**/part-*.jsonl*", recursive=True)):\n        opener = gzip.open if part.endswith(".gz") else open\n        with opener(part, "rt", encoding="utf-8") as f:\n            for line in f:\n                d = json.loads(line)\n                if d["id"] in need:\n                    ps = split_passages(d["t"], d["x"])\n                    docs[d["id"]] = ps if args.best_passages else ps[: args.max_passages]\n    return cands, qtext, docs\n\n\ndef worker(args) -> None:\n    import torch\n    from transformers import AutoModelForSequenceClassification, AutoTokenizer\n    cands, qtext, docs = load_inputs(args)\n    g, n = args.worker, args.ngpu\n    qids = sorted(cands["qid"].unique())[g::n]\n    cands = cands[cands["qid"].isin(set(qids))]\n    qwords = {q: words(t) for q, t in qtext.items()}\n\n    def passages(q: int, d: int) -> list[str]:\n        ps = docs[d]\n        return best_passages(ps, qwords[q], args.best_passages) if args.best_passages else ps\n\n    pairs = [(int(q), int(d), k, qtext[int(q)], p)\n             for q, d in zip(cands["qid"], cands["doc_id"]) if int(d) in docs\n             for k, p in enumerate(passages(int(q), int(d)))]\n    log(f"worker {g}: {len(qids)} queries, {len(pairs):,} pairs")\n    device = f"cuda:{g}" if torch.cuda.is_available() else "cpu"\n    tok = AutoTokenizer.from_pretrained(args.model)\n    model = AutoModelForSequenceClassification.from_pretrained(\n        args.model, torch_dtype=torch.float16 if device != "cpu" else torch.float32).to(device).eval()\n    order = np.argsort([-len(p[4]) for p in pairs], kind="stable")\n    scores = np.empty(len(pairs), dtype=np.float32)\n    for lo in range(0, len(order), args.batch):\n        idx = order[lo:lo + args.batch]\n        enc = tok([pairs[i][3] for i in idx], [pairs[i][4] for i in idx], padding=True, truncation="only_second",\n                  max_length=args.max_len, return_tensors="pt").to(device)\n        with torch.inference_mode():\n            scores[idx] = model(**enc).logits[:, 0].float().cpu().numpy()\n        if (lo // args.batch) % 200 == 0:\n            log(f"worker {g}: {lo + len(idx):,}/{len(pairs):,}")\n    df = pd.DataFrame({"qid": [p[0] for p in pairs], "doc_id": [p[1] for p in pairs],\n                       "passage": [p[2] for p in pairs], "score": scores})\n    if args.keep_all:\n        df.to_parquet(args.out / f"passages_w{g}.parquet", index=False)\n    best = df.loc[df.groupby(["qid", "doc_id"])["score"].idxmax()]\n    best.rename(columns={"passage": "best_passage"}).to_parquet(args.out / f"rerank_w{g}.parquet", index=False)\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument("--data", type=Path, required=True)\n    ap.add_argument("--cands", type=Path, required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--model", default="BAAI/bge-reranker-v2-m3")\n    ap.add_argument("--part", default="0/1")\n    ap.add_argument("--batch", type=int, default=32)\n    ap.add_argument("--max-len", type=int, default=512)\n    ap.add_argument("--max-queries", type=int, default=None)\n    ap.add_argument("--max-passages", type=int, default=None,\n                    help="cap on passages scored per doc; default None = whole document (user: no character limits)")\n    ap.add_argument("--best-passages", type=int, default=0,\n                    help="score only the K passages sharing the most query words (0 = all / --max-passages)")\n    ap.add_argument("--cut", default="", help="e.g. vi800,zh200,en200: keep cands with rank < N in their set")\n    ap.add_argument("--keep-all", action="store_true", help="also write passages.parquet (score of every passage)")\n    ap.add_argument("--worker", type=int, default=-1)\n    ap.add_argument("--ngpu", type=int, default=1)\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n    if args.worker >= 0:\n        worker(args)\n        return\n    import torch\n    n = max(1, torch.cuda.device_count())\n    procs = [subprocess.Popen([sys.executable, __file__, *sys.argv[1:], "--worker", str(g), "--ngpu", str(n)])\n             for g in range(n)]\n    if any(p.wait() != 0 for p in procs):\n        raise SystemExit("a worker failed")\n    parts = [args.out / f"rerank_w{g}.parquet" for g in range(n)]\n    pd.concat([pd.read_parquet(p) for p in parts]).to_parquet(args.out / "rerank.parquet", index=False)\n    if args.keep_all:\n        every = [args.out / f"passages_w{g}.parquet" for g in range(n)]\n        pd.concat([pd.read_parquet(p) for p in every]).to_parquet(args.out / "passages.parquet", index=False)\n        parts += every\n    for p in parts:\n        p.unlink()\n    log("done")\n\n\nif __name__ == "__main__":\n    main()\n'}
script = Path("/kaggle/tmp/m3_multi.py")
script.parent.mkdir(parents=True, exist_ok=True)
script.write_text(SRC, encoding="utf-8")
for mod_name, mod_src in MODULES.items():  # helper modules next to the script (importable)
    (script.parent / mod_name).write_text(mod_src, encoding="utf-8")
pip = []
if pip:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *pip], check=True)
args = [a.replace("{input}", "/kaggle/input").replace("{working}", "/kaggle/working") for a in ['--data', '{input}', '--cands', 'cands.parquet', '--out', '{working}', '--cut', 'vi800,zh200,en200', '--part', '3/4', '--batch', '32']]
subprocess.run([sys.executable, str(script), *args], check=True)
